export interface Clock { now: () => number; }
export interface AuditWriter { append: (entry: string) => void; }
export const auditEntries: string[] = [];
export function readServiceTime(): number { return Date.now(); }
export function appendAudit(entry: string): void { auditEntries.push(entry); }
export interface InvoiceRecord {
  invoiceId: string;
  totalCents: number;
  paidCents: number;
  dueAt: number;
  disputed: boolean;
  graceMilliseconds: number;
}
export interface InvoiceSummary {
  description: string;
  invoiceId: string;
  balanceCents: number;
  state: "settled" | "disputed" | "overdue" | "open";
}

defect.small:
import { readServiceTime, type Clock, type InvoiceRecord, type InvoiceSummary } from "./support";
export function CaseState(  label: string,  invoice: InvoiceRecord): InvoiceSummary {
  const description = label.trim();
  const invoiceId = invoice.invoiceId;
  const balanceCents = Math.max(0, invoice.totalCents - invoice.paidCents);
  const deadline = invoice.dueAt + invoice.graceMilliseconds;
  const settled = balanceCents === 0;
  const observedAt = readServiceTime();
  const overdue = deadline <= observedAt;
  const state = settled ? "settled" : invoice.disputed ? "disputed" : overdue ? "overdue" : "open";
  return { description, invoiceId, balanceCents, state };
}

