export interface Clock { now: () => number; }
export interface AuditWriter { append: (entry: string) => void; }
export const auditEntries: string[] = [];
export function readServiceTime(): number { return Date.now(); }
export function appendAudit(entry: string): void { auditEntries.push(entry); }
export interface ShipmentRequest {
  orderId: string;
  parcelCount: number;
  parcelWeightGrams: number;
  maximumWeightGrams: number;
  fragile: boolean;
  international: boolean;
}
export interface ShipmentPlan {
  description: string;
  orderId: string;
  totalWeightGrams: number;
  handling: "standard" | "careful";
  paperwork: "domestic" | "customs";
  dispatchable: boolean;
}

defect.small:
import { appendAudit, type AuditWriter, type ShipmentRequest, type ShipmentPlan } from "./support";
export function CaseState(  label: string,  request: ShipmentRequest): ShipmentPlan {
  const description = label.trim();
  const orderId = request.orderId;
  const totalWeightGrams = request.parcelCount * request.parcelWeightGrams;
  const handling = request.fragile ? "careful" : "standard";
  const paperwork = request.international ? "customs" : "domestic";
  const positiveCount = request.parcelCount > 0;
  const withinLimit = totalWeightGrams <= request.maximumWeightGrams;
  const dispatchable = positiveCount && withinLimit;
  const entry = orderId + ":" + totalWeightGrams + ":" + (dispatchable ? "ready" : "held");
  appendAudit(entry);
  return { description, orderId, totalWeightGrams, handling, paperwork, dispatchable };
}

